import { test } from 'node:test';
import assert from 'node:assert/strict';
import { somarValores, produtoMaisCaro, temProduto } from './solution.mjs';

test('somarValores soma todos os valores do estoque', () => {
  assert.equal(somarValores({ caneta: 2, caderno: 5, borracha: 1 }), 8);
});

test('estoque vazio: soma zero e produto mais caro null', () => {
  assert.equal(somarValores({}), 0);
  assert.equal(produtoMaisCaro({}), null);
});

test('produtoMaisCaro devolve o nome do produto com maior valor', () => {
  assert.equal(produtoMaisCaro({ caneta: 2, caderno: 5, borracha: 1 }), 'caderno');
});

test('temProduto confere se a chave existe no estoque', () => {
  assert.equal(temProduto({ caneta: 2 }, 'caneta'), true);
  assert.equal(temProduto({ caneta: 2 }, 'lapis'), false);
});

solutionCode:
export function somarValores(estoque) {
  let total = 0;
  for (const valor of Object.values(estoque)) {
    total = total + valor;
  }
  return total;
}

export function produtoMaisCaro(estoque) {
  let melhor = null;
  for (const [chave, valor] of Object.entries(estoque)) {
    if (melhor === null || valor > melhor.valor) {
      melhor = { chave, valor };
    }
  }
  return melhor === null ? null : melhor.chave;
}

export function temProduto(estoque, nome) {
  return estoque.hasOwnProperty(nome);
}
